-- etl-craft: rebuild-metadata

-- Mandatory configuration audit fields and a safe lifecycle history for tokens.

CREATE TEMP TABLE etl_craft_config_changes AS SELECT 'CFG_PIPELINES' AS table_name, CAST(PIPELINE_ID AS VARCHAR) AS row_key FROM CFG_PIPELINES WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL UNION ALL SELECT 'CFG_PIPELINE_DEPENDENCY' AS table_name, CAST(PIPELINE_DEPENDENCY_ID AS VARCHAR) AS row_key FROM CFG_PIPELINE_DEPENDENCY WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL UNION ALL SELECT 'CFG_TASKS' AS table_name, CAST(TASK_ID AS VARCHAR) AS row_key FROM CFG_TASKS WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL UNION ALL SELECT 'CFG_TASK_DEPENDENCY' AS table_name, CAST(TASK_DEPENDENCY_ID AS VARCHAR) AS row_key FROM CFG_TASK_DEPENDENCY WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL UNION ALL SELECT 'CFG_TASK_PARAMETERS' AS table_name, CAST(TASK_PARAMETER_ID AS VARCHAR) AS row_key FROM CFG_TASK_PARAMETERS WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL UNION ALL SELECT 'CFG_BUSINESS_RULES' AS table_name, CAST(BUSINESS_RULE_ID AS VARCHAR) AS row_key FROM CFG_BUSINESS_RULES WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL UNION ALL SELECT 'CFG_API_TOKENS' AS table_name, CAST(TOKEN_ID AS VARCHAR) AS row_key FROM CFG_API_TOKENS UNION ALL SELECT 'CFG_SOURCE_COLUMNS' AS table_name, CAST(SOURCE_COLUMN_ID AS VARCHAR) AS row_key FROM CFG_SOURCE_COLUMNS WHERE CREATED_BY IS NULL OR CREATE_DATE IS NULL OR UPDATED_BY IS NULL OR UPDATED_DATE IS NULL;

CREATE TEMP TABLE etl_craft_config_sequences AS SELECT name, seq FROM sqlite_sequence WHERE name LIKE 'CFG_%';

CREATE TABLE CFG_PIPELINES_new (
    PIPELINE_ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    PIPELINE_CODE        VARCHAR NOT NULL,
    PIPELINE_NAME        VARCHAR NOT NULL,
    DESCRIPTION          VARCHAR,
    RUN_SCHEDULE         VARCHAR,
    SLA_IN_HOURS         NUMERIC,
    REFRESH_TYPE         VARCHAR NOT NULL,
    ACTIVE_FLAG          VARCHAR NOT NULL DEFAULT 'Y',
    PIPELINE_PARAMETERS  TEXT,
    CREATED_BY           VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE          TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY           VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE         TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    SCHEDULE_TIMEZONE VARCHAR,
    CATCHUP VARCHAR(1) NOT NULL DEFAULT 'N' CONSTRAINT ck_schedule_catchup CHECK (CATCHUP IN ('Y','N')),
    MAX_CATCHUP_RUNS INT NOT NULL DEFAULT 1 CONSTRAINT ck_schedule_catchup_runs CHECK (MAX_CATCHUP_RUNS > 0 AND typeof(MAX_CATCHUP_RUNS) = 'integer'),
    OVERLAP_POLICY VARCHAR NOT NULL DEFAULT 'SKIP' CONSTRAINT ck_schedule_overlap CHECK (OVERLAP_POLICY IN ('SKIP','QUEUE')),
    SCHEDULE_START_DATE DATE,
    CONSTRAINT ck_pipelines_code CHECK (PIPELINE_CODE GLOB '[A-Za-z]*' AND PIPELINE_CODE NOT GLOB '*[^A-Za-z0-9_]*' AND length(PIPELINE_CODE) <= 128 AND instr(PIPELINE_CODE, char(0)) = 0),
    CONSTRAINT ck_pipelines_refresh_type CHECK (REFRESH_TYPE IN ('FULL', 'INCREMENTAL')),
    CONSTRAINT ck_pipelines_active_flag  CHECK (ACTIVE_FLAG IN ('Y', 'N')),
    CONSTRAINT ck_pipelines_parameters_json
        CHECK (PIPELINE_PARAMETERS IS NULL OR json_valid(PIPELINE_PARAMETERS))
);

INSERT INTO CFG_PIPELINES_new (PIPELINE_ID, PIPELINE_CODE, PIPELINE_NAME, DESCRIPTION, RUN_SCHEDULE, SLA_IN_HOURS, REFRESH_TYPE, ACTIVE_FLAG, PIPELINE_PARAMETERS, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE, SCHEDULE_TIMEZONE, CATCHUP, MAX_CATCHUP_RUNS, OVERLAP_POLICY, SCHEDULE_START_DATE) SELECT PIPELINE_ID, PIPELINE_CODE, PIPELINE_NAME, DESCRIPTION, RUN_SCHEDULE, SLA_IN_HOURS, REFRESH_TYPE, ACTIVE_FLAG, PIPELINE_PARAMETERS, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), SCHEDULE_TIMEZONE, CATCHUP, MAX_CATCHUP_RUNS, OVERLAP_POLICY, SCHEDULE_START_DATE FROM CFG_PIPELINES;

DROP TABLE CFG_PIPELINES;

ALTER TABLE CFG_PIPELINES_new RENAME TO CFG_PIPELINES;

CREATE UNIQUE INDEX ux_pipelines_code_active
    ON CFG_PIPELINES (PIPELINE_CODE) WHERE ACTIVE_FLAG = 'Y';

CREATE TABLE CFG_PIPELINE_DEPENDENCY_new (
    PIPELINE_DEPENDENCY_ID  INTEGER PRIMARY KEY AUTOINCREMENT,
    PIPELINE_ID             BIGINT NOT NULL REFERENCES CFG_PIPELINES(PIPELINE_ID),
    DEPENDS_ON_PIPELINE_ID  BIGINT NOT NULL REFERENCES CFG_PIPELINES(PIPELINE_ID),
    DEPENDENCY_TYPE         VARCHAR NOT NULL,
    ACTIVE_FLAG             VARCHAR NOT NULL DEFAULT 'Y',
    CREATED_BY              VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE             TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY              VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE            TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    CONSUME_REPAIRS         VARCHAR(1) NOT NULL DEFAULT 'Y' CONSTRAINT ck_pipedep_consume_repairs CHECK (CONSUME_REPAIRS IN ('Y','N')),
    CONSTRAINT ck_pipedep_type        CHECK (DEPENDENCY_TYPE IN ('SUCCESS','FAILURE','ALWAYS','HAS_DATA')),
    CONSTRAINT ck_pipedep_active_flag CHECK (ACTIVE_FLAG IN ('Y','N')),
    CONSTRAINT ck_pipedep_no_self_dep CHECK (PIPELINE_ID <> DEPENDS_ON_PIPELINE_ID)
);

INSERT INTO CFG_PIPELINE_DEPENDENCY_new (PIPELINE_DEPENDENCY_ID, PIPELINE_ID, DEPENDS_ON_PIPELINE_ID, DEPENDENCY_TYPE, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE, CONSUME_REPAIRS) SELECT PIPELINE_DEPENDENCY_ID, PIPELINE_ID, DEPENDS_ON_PIPELINE_ID, DEPENDENCY_TYPE, ACTIVE_FLAG, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), CONSUME_REPAIRS FROM CFG_PIPELINE_DEPENDENCY;

DROP TABLE CFG_PIPELINE_DEPENDENCY;

ALTER TABLE CFG_PIPELINE_DEPENDENCY_new RENAME TO CFG_PIPELINE_DEPENDENCY;

CREATE UNIQUE INDEX ux_pipedep_edge_active
    ON CFG_PIPELINE_DEPENDENCY (PIPELINE_ID, DEPENDS_ON_PIPELINE_ID, DEPENDENCY_TYPE)
    WHERE ACTIVE_FLAG = 'Y';

CREATE INDEX ix_pipedep_depends_on ON CFG_PIPELINE_DEPENDENCY (DEPENDS_ON_PIPELINE_ID);

CREATE TABLE CFG_TASKS_new (
    TASK_ID              INTEGER PRIMARY KEY AUTOINCREMENT,
    TASK_CODE            VARCHAR NOT NULL,
    TASK_TYPE            VARCHAR NOT NULL,
    PIPELINE_ID          BIGINT NOT NULL REFERENCES CFG_PIPELINES(PIPELINE_ID),
    HANDLER              VARCHAR NOT NULL,
    RUN_CONDITION        VARCHAR,
    RUN_CONDITION_COUNT  INT,
    ACTIVE_FLAG          VARCHAR NOT NULL DEFAULT 'Y',
    CREATED_BY           VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE          TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY           VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE         TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    CONSTRAINT ck_tasks_code CHECK (TASK_CODE GLOB '[A-Za-z]*' AND TASK_CODE NOT GLOB '*[^A-Za-z0-9_]*' AND length(TASK_CODE) <= 128 AND instr(TASK_CODE, char(0)) = 0),
    CONSTRAINT ck_tasks_task_type     CHECK (TASK_TYPE IN ('INGESTION','ETL')),
    CONSTRAINT ck_tasks_handler       CHECK (HANDLER IN ('PYTHON','SQL','BUSINESS_RULES','EMAIL_ALERT','EVENT_WAIT')),
    CONSTRAINT ck_tasks_active_flag   CHECK (ACTIVE_FLAG IN ('Y','N')),
    CONSTRAINT ck_tasks_run_condition CHECK (RUN_CONDITION IS NULL OR RUN_CONDITION IN ('ALL','ANY','N')),
    CONSTRAINT ck_tasks_run_condition_count CHECK (
        (COALESCE(RUN_CONDITION, '') = 'N' AND RUN_CONDITION_COUNT IS NOT NULL
            AND RUN_CONDITION_COUNT >= 1)
        OR (RUN_CONDITION IS NOT 'N' AND RUN_CONDITION_COUNT IS NULL)
    )
);

INSERT INTO CFG_TASKS_new (TASK_ID, TASK_CODE, TASK_TYPE, PIPELINE_ID, HANDLER, RUN_CONDITION, RUN_CONDITION_COUNT, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE) SELECT TASK_ID, TASK_CODE, TASK_TYPE, PIPELINE_ID, HANDLER, RUN_CONDITION, RUN_CONDITION_COUNT, ACTIVE_FLAG, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')) FROM CFG_TASKS;

DROP TABLE CFG_TASKS;

ALTER TABLE CFG_TASKS_new RENAME TO CFG_TASKS;

CREATE UNIQUE INDEX ux_tasks_code_active
    ON CFG_TASKS (PIPELINE_ID, TASK_CODE) WHERE ACTIVE_FLAG = 'Y';

CREATE TABLE CFG_TASK_DEPENDENCY_new (
    TASK_DEPENDENCY_ID      INTEGER PRIMARY KEY AUTOINCREMENT,
    PIPELINE_ID             BIGINT NOT NULL REFERENCES CFG_PIPELINES(PIPELINE_ID),
    TASK_ID                 BIGINT NOT NULL REFERENCES CFG_TASKS(TASK_ID),
    DEPENDS_ON_PIPELINE_ID  BIGINT REFERENCES CFG_PIPELINES(PIPELINE_ID),
    DEPENDS_ON_TASK_ID      BIGINT NOT NULL REFERENCES CFG_TASKS(TASK_ID),
    DEPENDENCY_TYPE         VARCHAR NOT NULL,
    ACTIVE_FLAG             VARCHAR NOT NULL DEFAULT 'Y',
    CREATED_BY              VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE             TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY              VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE            TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    CONSUME_REPAIRS         VARCHAR(1) NOT NULL DEFAULT 'Y' CONSTRAINT ck_taskdep_consume_repairs CHECK (CONSUME_REPAIRS IN ('Y','N')),
    CONSTRAINT ck_taskdep_type        CHECK (DEPENDENCY_TYPE IN ('SUCCESS','FAILURE','ALWAYS','HAS_DATA')),
    CONSTRAINT ck_taskdep_active_flag CHECK (ACTIVE_FLAG IN ('Y','N')),
    CONSTRAINT ck_taskdep_no_self_dep CHECK (NOT (TASK_ID = DEPENDS_ON_TASK_ID AND PIPELINE_ID = DEPENDS_ON_PIPELINE_ID))
);

INSERT INTO CFG_TASK_DEPENDENCY_new (TASK_DEPENDENCY_ID, PIPELINE_ID, TASK_ID, DEPENDS_ON_PIPELINE_ID, DEPENDS_ON_TASK_ID, DEPENDENCY_TYPE, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE, CONSUME_REPAIRS) SELECT TASK_DEPENDENCY_ID, PIPELINE_ID, TASK_ID, DEPENDS_ON_PIPELINE_ID, DEPENDS_ON_TASK_ID, DEPENDENCY_TYPE, ACTIVE_FLAG, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), CONSUME_REPAIRS FROM CFG_TASK_DEPENDENCY;

DROP TABLE CFG_TASK_DEPENDENCY;

ALTER TABLE CFG_TASK_DEPENDENCY_new RENAME TO CFG_TASK_DEPENDENCY;

CREATE UNIQUE INDEX ux_taskdep_edge_active
    ON CFG_TASK_DEPENDENCY (TASK_ID, DEPENDS_ON_PIPELINE_ID, DEPENDS_ON_TASK_ID, DEPENDENCY_TYPE)
    WHERE ACTIVE_FLAG = 'Y';

CREATE INDEX ix_taskdep_depends_on ON CFG_TASK_DEPENDENCY (DEPENDS_ON_TASK_ID);

CREATE TABLE CFG_TASK_PARAMETERS_new (
    TASK_PARAMETER_ID  INTEGER PRIMARY KEY AUTOINCREMENT,
    TASK_ID            BIGINT NOT NULL REFERENCES CFG_TASKS(TASK_ID),
    PARAMETER_NAME     VARCHAR NOT NULL,
    PARAMETER_VALUE    VARCHAR,
    ACTIVE_FLAG        VARCHAR NOT NULL DEFAULT 'Y',
    CREATED_BY         VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE        TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY         VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE       TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    CONSTRAINT ck_taskparameters_active_flag CHECK (ACTIVE_FLAG IN ('Y','N'))
);

INSERT INTO CFG_TASK_PARAMETERS_new (TASK_PARAMETER_ID, TASK_ID, PARAMETER_NAME, PARAMETER_VALUE, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE) SELECT TASK_PARAMETER_ID, TASK_ID, PARAMETER_NAME, PARAMETER_VALUE, ACTIVE_FLAG, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')) FROM CFG_TASK_PARAMETERS;

DROP TABLE CFG_TASK_PARAMETERS;

ALTER TABLE CFG_TASK_PARAMETERS_new RENAME TO CFG_TASK_PARAMETERS;

CREATE UNIQUE INDEX ux_taskparameters_name_active
    ON CFG_TASK_PARAMETERS (TASK_ID, PARAMETER_NAME) WHERE ACTIVE_FLAG = 'Y';

CREATE TABLE CFG_BUSINESS_RULES_new (
    BUSINESS_RULE_ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    BUSINESS_RULE_NAME        VARCHAR NOT NULL,
    PIPELINE_ID               BIGINT NOT NULL REFERENCES CFG_PIPELINES(PIPELINE_ID),
    TASK_ID                   BIGINT NOT NULL REFERENCES CFG_TASKS(TASK_ID),
    BUSINESS_RULE_SQL         VARCHAR NOT NULL,
    BUSINESS_RULE_TYPE        VARCHAR NOT NULL,
    BUSINESS_RULE_KEY_COLUMN  VARCHAR NOT NULL,
    TARGET_TABLE              VARCHAR NOT NULL,
    SEQUENCE_NUMBER           BIGINT NOT NULL,
    ACTIVE_FLAG               VARCHAR NOT NULL DEFAULT 'Y',
    CREATED_BY                VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE               TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY                VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE              TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    CONSTRAINT ck_br_type        CHECK (BUSINESS_RULE_TYPE IN ('INCOMPLETE','REJECT','REPORT')),
    CONSTRAINT ck_br_active_flag CHECK (ACTIVE_FLAG IN ('Y','N'))
);

INSERT INTO CFG_BUSINESS_RULES_new (BUSINESS_RULE_ID, BUSINESS_RULE_NAME, PIPELINE_ID, TASK_ID, BUSINESS_RULE_SQL, BUSINESS_RULE_TYPE, BUSINESS_RULE_KEY_COLUMN, TARGET_TABLE, SEQUENCE_NUMBER, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE) SELECT BUSINESS_RULE_ID, BUSINESS_RULE_NAME, PIPELINE_ID, TASK_ID, BUSINESS_RULE_SQL, BUSINESS_RULE_TYPE, BUSINESS_RULE_KEY_COLUMN, TARGET_TABLE, SEQUENCE_NUMBER, ACTIVE_FLAG, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')) FROM CFG_BUSINESS_RULES;

DROP TABLE CFG_BUSINESS_RULES;

ALTER TABLE CFG_BUSINESS_RULES_new RENAME TO CFG_BUSINESS_RULES;

CREATE UNIQUE INDEX ux_br_name_active
    ON CFG_BUSINESS_RULES (TASK_ID, BUSINESS_RULE_NAME) WHERE ACTIVE_FLAG = 'Y';

CREATE INDEX ix_br_pipeline ON CFG_BUSINESS_RULES (PIPELINE_ID);

CREATE TABLE CFG_API_TOKENS_new (
    TOKEN_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    NAME VARCHAR(128) NOT NULL,
    TOKEN_SHA256 VARCHAR(64) NOT NULL UNIQUE,
    ROLE VARCHAR(16) NOT NULL CHECK (ROLE IN ('viewer', 'operator', 'admin')),
    PROJECT_ID BIGINT,
    CREATED_BY VARCHAR(128) NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    EXPIRES_AT TIMESTAMP,
    REVOKED_AT TIMESTAMP,
    ACTIVE_FLAG VARCHAR(1) NOT NULL DEFAULT 'Y' CHECK (ACTIVE_FLAG IN ('Y','N')),
    UPDATED_BY VARCHAR(128) NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')
);

INSERT INTO CFG_API_TOKENS_new (TOKEN_ID, NAME, TOKEN_SHA256, ROLE, PROJECT_ID, EXPIRES_AT, REVOKED_AT, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE) SELECT TOKEN_ID, NAME, TOKEN_SHA256, ROLE, PROJECT_ID, EXPIRES_AT, REVOKED_AT, CASE WHEN REVOKED_AT IS NULL THEN 'Y' ELSE 'N' END, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), etl_craft_actor(), (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00') FROM CFG_API_TOKENS;

DROP TABLE CFG_API_TOKENS;

ALTER TABLE CFG_API_TOKENS_new RENAME TO CFG_API_TOKENS;

CREATE TABLE CFG_SOURCE_COLUMNS_new (
    SOURCE_COLUMN_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    TABLE_NAME VARCHAR NOT NULL,
    COLUMN_NAME VARCHAR NOT NULL,
    DATA_TYPE VARCHAR NOT NULL,
    COLUMN_POSITION INTEGER NOT NULL CONSTRAINT ck_source_column_position CHECK (COLUMN_POSITION > 0 AND typeof(COLUMN_POSITION) = 'integer'),
    ACTIVE_FLAG VARCHAR NOT NULL DEFAULT 'Y' CONSTRAINT ck_source_column_active CHECK (ACTIVE_FLAG IN ('Y','N')),
    CREATED_BY VARCHAR NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00'),
    UPDATED_BY VARCHAR NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE TIMESTAMP NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')
);

INSERT INTO CFG_SOURCE_COLUMNS_new (SOURCE_COLUMN_ID, TABLE_NAME, COLUMN_NAME, DATA_TYPE, COLUMN_POSITION, ACTIVE_FLAG, CREATED_BY, CREATE_DATE, UPDATED_BY, UPDATED_DATE) SELECT SOURCE_COLUMN_ID, TABLE_NAME, COLUMN_NAME, DATA_TYPE, COLUMN_POSITION, ACTIVE_FLAG, COALESCE(CREATED_BY, 'etl-craft-migration-0026'), COALESCE(CREATE_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')), COALESCE(UPDATED_BY, 'etl-craft-migration-0026'), COALESCE(UPDATED_DATE, (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00')) FROM CFG_SOURCE_COLUMNS;

DROP TABLE CFG_SOURCE_COLUMNS;

ALTER TABLE CFG_SOURCE_COLUMNS_new RENAME TO CFG_SOURCE_COLUMNS;

CREATE UNIQUE INDEX ux_source_column_active ON CFG_SOURCE_COLUMNS (lower(TABLE_NAME), lower(COLUMN_NAME)) WHERE ACTIVE_FLAG = 'Y';

CREATE UNIQUE INDEX ux_source_position_active ON CFG_SOURCE_COLUMNS (lower(TABLE_NAME), COLUMN_POSITION) WHERE ACTIVE_FLAG = 'Y';

UPDATE sqlite_sequence SET seq=max(seq, coalesce((SELECT s.seq FROM etl_craft_config_sequences s WHERE s.name=sqlite_sequence.name), seq));

INSERT INTO sqlite_sequence (name,seq) SELECT name,seq FROM etl_craft_config_sequences s WHERE NOT EXISTS (SELECT 1 FROM sqlite_sequence c WHERE c.name=s.name);

DROP TABLE etl_craft_config_sequences;

ALTER TABLE AUD_CFG_API_TOKENS_HISTORY ADD COLUMN ACTIVE_FLAG VARCHAR(1);

ALTER TABLE AUD_CFG_API_TOKENS_HISTORY ADD COLUMN UPDATED_BY VARCHAR(128);

ALTER TABLE AUD_CFG_API_TOKENS_HISTORY ADD COLUMN UPDATED_DATE TIMESTAMP;

CREATE TEMP TABLE etl_craft_config_time AS SELECT (strftime('%Y-%m-%d %H:%M:%f', 'now') || '000+00:00') AS changed_at;

