INSERT INTO AUD_CFG_PIPELINES_HISTORY (CHANGE_ID,VALID_FROM,VALID_TO,CURRENT_FLAG,OPERATION,ACTOR,ACTOR_KIND,MIGRATION,PIPELINE_ID,PIPELINE_CODE,PIPELINE_NAME,DESCRIPTION,RUN_SCHEDULE,SLA_IN_HOURS,REFRESH_TYPE,ACTIVE_FLAG,PIPELINE_PARAMETERS,CREATED_BY,CREATE_DATE,UPDATED_BY,UPDATED_DATE,SCHEDULE_TIMEZONE,CATCHUP,MAX_CATCHUP_RUNS,OVERLAP_POLICY,SCHEDULE_START_DATE) SELECT (SELECT COALESCE(MAX(m),0) FROM (SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_PIPELINES_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_PIPELINE_DEPENDENCY_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TASKS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TASK_DEPENDENCY_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TASK_PARAMETERS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_BUSINESS_RULES_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_API_TOKENS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_SOURCE_COLUMNS_HISTORY) all_changes)+ROW_NUMBER() OVER (ORDER BY PIPELINE_ID),(SELECT changed_at FROM etl_craft_config_time),'9999-12-31 23:59:59.000000+00:00','Y','UPDATE',etl_craft_actor(),etl_craft_actor_kind(),'engine/0026_config_base_contract.sql',PIPELINE_ID,PIPELINE_CODE,PIPELINE_NAME,DESCRIPTION,RUN_SCHEDULE,SLA_IN_HOURS,REFRESH_TYPE,ACTIVE_FLAG,PIPELINE_PARAMETERS,CREATED_BY,CREATE_DATE,UPDATED_BY,UPDATED_DATE,SCHEDULE_TIMEZONE,CATCHUP,MAX_CATCHUP_RUNS,OVERLAP_POLICY,SCHEDULE_START_DATE FROM CFG_PIPELINES WHERE CAST(PIPELINE_ID AS VARCHAR) IN (SELECT row_key FROM etl_craft_config_changes WHERE table_name='CFG_PIPELINES');

